import sys
import functools

def main():
    def optimal_score(cards):
        @functools.lru_cache(None)
        def dp(i, j, turn):
            if i > j:
                return 0
            if i == j:
                return cards[i] if turn else 0
            if turn:
                # Alice's turn: she wants to maximize her score minus Bob's score
                return max(cards[i] + dp(i + 1, j, not turn), cards[j] + dp(i, j - 1, not turn))
            else:
                # Bob's turn: he wants to minimize Alice's score minus his score
                return min(-cards[i] + dp(i + 1, j, not turn), -cards[j] + dp(i, j - 1, not turn))

        return dp(0, len(cards) - 1, True)

    N = int(sys.stdin.readline())
    cards = list(map(int, sys.stdin.readline().split()))
    result = optimal_score(cards)
    print(result)

